import { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import DeleteIcon from '@mui/icons-material/Delete';
import CircularProgress from '@mui/material/CircularProgress';
import './friends.scss';

const Friends = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const navigate = useNavigate();
  const [friends, setFriends] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [removingFriendId, setRemovingFriendId] = useState(null);

  const fetchFriends = async () => {
    const token = localStorage.getItem('token');
    if (!token) {
      setError('Please log in to view friends.');
      setLoading(false);
      return;
    }

    try {
      console.log(`Friends: Fetching friends for user ID: ${currentUser?.id}`);
      const res = await axios.get(`http://localhost:5000/api/users/${currentUser.id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Friends: Fetched friends=', res.data.friends);
      setFriends(res.data.friends || []);
      setError(null);
    } catch (err) {
      console.error('Friends: Error fetching friends:', err.message);
      console.error('Friends: Response:', err.response?.data);
      const errorMessage = err.response?.data?.message || 'Failed to load friends.';
      setError(errorMessage);
      setFriends([]);
    }
  };

  useEffect(() => {
    if (!currentUser) {
      console.log('Friends: No currentUser, redirecting to login');
      navigate('/login');
      return;
    }

    setLoading(true);
    fetchFriends().finally(() => setLoading(false));

    // Polling for friend list updates
    const interval = setInterval(() => {
      console.log('Friends: Polling for friends');
      fetchFriends();
    }, 5000); // Every 5 seconds

    return () => {
      console.log('Friends: Cleaning up polling interval');
      clearInterval(interval);
    };
  }, [currentUser, navigate]);

  const handleRemoveFriend = async (friendId) => {
    setRemovingFriendId(friendId);
    try {
      const token = localStorage.getItem('token');
      console.log(`Friends: Removing friend with ID: ${friendId}`);
      const res = await axios.delete(`http://localhost:5000/api/users/${friendId}/friends`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Friends: Friend removed=', res.data);
      setFriends(friends.filter((friend) => friend._id !== friendId));
      alert('Friend removed successfully!');
    } catch (err) {
      console.error('Friends: Error removing friend:', err.message);
      console.error('Friends: Response:', err.response?.data);
      const errorMessage = err.response?.data?.message || 'Failed to remove friend.';
      setError(errorMessage);
    } finally {
      setRemovingFriendId(null);
    }
  };

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Friends: No profile picture provided, using default');
      return '/default-avatar.png';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Friends: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Friends: Profile picture URL:', url);
    fetch(url)
      .then((res) => console.log('Friends: User image fetch status:', res.status, res.statusText))
      .catch((err) => console.error('Friends: User image fetch error:', err));
    return url;
  };

  if (!currentUser) {
    return <div className={`friends ${darkMode ? 'theme-dark' : 'theme-light'}`}>Please log in to view friends.</div>;
  }

  if (loading) {
    return <div className={`friends ${darkMode ? 'theme-dark' : 'theme-light'}`}>Loading...</div>;
  }

  if (error) {
    return <div className={`friends ${darkMode ? 'theme-dark' : 'theme-light'} error`}>{error}</div>;
  }

  return (
    <div className={`friends ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <h2>{currentUser.name}'s Friends</h2>
      <div className="friends-list">
        {friends.length > 0 ? (
          friends.map((friend) => (
            <div key={friend._id} className="friend-card">
              <img
                src={getProfilePictureUrl(friend.profilePicture)}
                alt={`${friend.name}'s profile`}
                className="avatar"
                onError={(e) => {
                  console.error(`Friends: Image load error for ${friend.name}:`, e);
                  e.target.src = '/default-avatar.png';
                }}
              />
              <div className="friend-info">
                <span className="username">{friend.username}</span>
                <span className="name">{friend.name}</span>
              </div>
              <button
                className="remove-friend-btn"
                onClick={() => handleRemoveFriend(friend._id)}
                title={`Remove ${friend.username} as a friend`}
                disabled={removingFriendId === friend._id}
              >
                {removingFriendId === friend._id ? (
                  <CircularProgress size={20} color="inherit" />
                ) : (
                  <>
                    <DeleteIcon /> Remove Friend
                  </>
                )}
              </button>
            </div>
          ))
        ) : (
          <p>No friends found.</p>
        )}
      </div>
    </div>
  );
};

export default Friends;
